import 'dart:convert';class EncryptUtils {  static String rc4Decrypt(String encryptedText, String key) {    List<int> s = List<int>.generate(256, (int index) => index);    int i = 0, j = 0, x, temp;    List<int> keyList = utf8.encode(key);    List<int> cipher = [];    if (isHexString(encryptedText)) {      // 使用手动创建的函数进行将十六进制转换为字节流      cipher = hexStringToBytes(encryptedText);    }    for (int i = 0; i < 256; i++) {      j = (j + s[i] + keyList[i % keyList.length]) % 256;      temp = s[i];      s[i] = s[j];      s[j] = temp;    }    i = j = 0;    List<int> result = [];    for (int y = 0; y < cipher.length; y++) {      i = (i + 1) % 256;      j = (j + s[i]) % 256;      temp = s[i];      s[i] = s[j];      s[j] = temp;      x = (s[i] + s[j]) % 256;      result.add(cipher[y] ^ s[x]);    }    return utf8.decode(result);  }  // 检查字符串是否为十六进制编码  static bool isHexString(String input) {    final RegExp hexRegex = RegExp(r'^[0-9A-Fa-f]+$');    return hexRegex.hasMatch(input);  }  // 将十六进制转换为字节流  static List<int> hexStringToBytes(String hexString) {    List<int> result = [];    for (int i = 0; i < hexString.length; i += 2) {      String hex = hexString.substring(i, i + 2);      result.add(int.parse(hex, radix: 16));    }    return result;  }}